#!/usr/bin/env python3\n"""Static BPMN/DMN structural checks; this does not replace Camunda deployment tests."""\nfrom pathlib import Path\nimport sys\nimport xml.etree.ElementTree as ET\n\nROOT = Path(__file__).resolve().parents[1]\nchecks = []\ndef check(name, ok, detail): checks.append((name, bool(ok), detail))\ndef parse(rel):\n    try: return ET.parse(ROOT / rel).getroot()\n    except Exception as exc:\n        check(f"XML parse: {rel}", False, str(exc))\n        return None\n\nbpmn_path = "src/main/resources/bpmn/paymentApprovalProcess.bpmn"\ndmn_path = "src/main/resources/dmn/nivelAprobacionPago.dmn"\nbpmn = parse(bpmn_path)\ndmn = parse(dmn_path)\nif bpmn is not None:\n    ns = {"b": "http://www.omg.org/spec/BPMN/20100524/MODEL"}\n    ids = [el.attrib.get("id") for el in bpmn.iter() if el.attrib.get("id")]\n    idset = set(ids)\n    refs_ok = True\n    missing = []\n    for el in bpmn.iter():\n        for attr in ("sourceRef", "targetRef", "attachedToRef", "processRef", "messageRef"):\n            ref = el.attrib.get(attr)\n            if ref and ref not in idset:\n                refs_ok = False; missing.append(f"{el.tag}:{attr}={ref}")\n    check("BPMN IDs unique", len(ids) == len(idset), "Los IDs del modelo deben ser únicos.")\n    check("BPMN referencias resolubles", refs_ok, "; ".join(missing) or "Todas las referencias estáticas resuelven.")\n    gateways = [el for el in bpmn.iter() if el.tag.endswith("exclusiveGateway")]\n    match_gate = next((g for g in gateways if g.attrib.get("id") == "GW_Match"), None)\n    check("Match gateway fail-closed", match_gate is not None and match_gate.attrib.get("default") == "F_Match_Fail",\n          "Una salida ausente o no válida no debe alcanzar el registro de pago.")\n    flows = [el for el in bpmn.iter() if el.tag.endswith("sequenceFlow")]\n    success = next((f for f in flows if f.attrib.get("id") == "F_Match_OK"), None)\n    condition = "".join(success.itertext()) if success is not None else ""\n    check("Match requiere estado MATCH y matchId", "matchResult.estado == 'MATCH'" in condition and "matchResult.matchId != null" in condition,\n          "Solo evidencia persistida explícita puede continuar.")\n    camunda_ns = "{http://camunda.org/schema/1.0/bpmn}"\n    decision_task = next((el for el in bpmn.iter() if el.attrib.get("id") == "Task_EvaluatePaymentApproval"), None)\n    check("Payment BPMN invokes approval DMN", decision_task is not None\n          and decision_task.tag.endswith("businessRuleTask")\n          and decision_task.attrib.get(camunda_ns + "decisionRef") == "nivelAprobacionPago"\n          and decision_task.attrib.get(camunda_ns + "resultVariable") == "approvalDecision",\n          "La policy DMN debe ejecutarse y su salida debe quedar en una variable explícita.")\n    approval_gateway = next((g for g in gateways if g.attrib.get("id") == "GW_ApprovalPolicy"), None)\n    check("Approval gateway fails closed to manual review", approval_gateway is not None\n          and approval_gateway.attrib.get("default") == "F_Approval_Manual",\n          "La rama por defecto y cualquier salida no automática deben detener el pago.")\n    approval_auto = next((f for f in flows if f.attrib.get("id") == "F_Approval_Auto"), None)\n    auto_condition = "".join(approval_auto.itertext()) if approval_auto is not None else ""\n    check("Only no-manual-review decision reaches approval-evidence delegate", approval_auto is not None\n          and approval_auto.attrib.get("targetRef") == "Task_PersistPolicyApproval"\n          and "approvalDecision.requiereRevisionManual == false" in auto_condition,\n          "Solo la salida explícita de política automática puede persistirse como aprobación.")\n    policy_persist_task = next((el for el in bpmn.iter() if el.attrib.get("id") == "Task_PersistPolicyApproval"), None)\n    check("Durable policy approval precedes payment registration", policy_persist_task is not None\n          and policy_persist_task.attrib.get("{http://camunda.org/schema/1.0/bpmn}delegateExpression") == "${persistAutomaticPaymentApprovalDelegate}"\n          and any(f.attrib.get("id") == "F_Persist_Approval" and f.attrib.get("sourceRef") == "Task_PersistPolicyApproval" and f.attrib.get("targetRef") == "Task_RegistrarPago" for f in flows),\n          "El resultado DMN debe tener evidencia durable antes del delegate que crea la instrucción.")\n    approval_manual = next((f for f in flows if f.attrib.get("id") == "F_Approval_Manual"), None)\n    check("Manual approval route cannot create payment", approval_manual is not None\n          and approval_manual.attrib.get("targetRef") == "End_ApprovalRequired"\n          and approval_manual.attrib.get("targetRef") != "Task_RegistrarPago",\n          "Sin servicio autenticado de aprobación durable, la ruta manual termina sin pago.")\n    flow_by_id = {f.attrib.get("id"): f for f in flows}\n    register_task = next((el for el in bpmn.iter() if el.attrib.get("id") == "Task_RegistrarPago"), None)\n    incoming_payment = [e.text for e in register_task.findall("b:incoming", ns)] if register_task is not None else []\n    check("Payment registration only receives persisted-policy approval flow", incoming_payment == ["F_Persist_Approval"]\n          and flow_by_id.get("F_Approval_Auto", ET.Element("dummy")).attrib.get("targetRef") == "Task_PersistPolicyApproval"\n          and flow_by_id.get("F_Persist_Approval", ET.Element("dummy")).attrib.get("targetRef") == "Task_RegistrarPago",\n          "No debe existir una conexión alternativa desde los gates de match/política al registro de pago.")\nif dmn is not None:\n    ns = {"d": "https://www.omg.org/spec/DMN/20191111/MODEL/"}\n    rules = dmn.findall(".//d:rule", ns)\n    check("DMN tiene reglas de aprobación", len(rules) >= 4, f"Reglas detectadas: {len(rules)}")\n    check("DMN requires currency input and emits policy version",\n          dmn.find(".//d:input[@id='input_moneda']", ns) is not None\n          and dmn.find(".//d:output[@name='policyVersion']", ns) is not None,\n          "Los umbrales son específicos de moneda y la evidencia conserva la versión exacta de política.")\n    automatic = next((r for r in rules if r.attrib.get("id") == "rule_automatica"), None)\n    automatic_inputs = automatic.findall("d:inputEntry/d:text", ns) if automatic is not None else []\n    automatic_outputs = automatic.findall("d:outputEntry/d:text", ns) if automatic is not None else []\n    check("Automatic rule only accepts MXN and policy version is explicit",\n          len(automatic_inputs) == 2 and automatic_inputs[1].text.strip() == '"MXN"'\n          and len(automatic_outputs) == 3 and automatic_outputs[2].text.strip() == '"nivelAprobacionPago-v2-MXN"',\n          "No se da aprobación automática a otra moneda ni se deja la decisión sin versión.")\n    gerente = next((r for r in rules if r.attrib.get("id") == "rule_gerente"), None)\n    outputs = gerente.findall("d:outputEntry/d:text", ns) if gerente is not None else []\n    manual_review = outputs[1] if len(outputs) > 1 else None\n    check("Ruta GERENTE exige revisión manual", manual_review is not None and manual_review.text.strip() == "true",\n          "La salida de la ruta GERENTE no puede declarar revisión manual falsa.")\n\nerrors = 0\nfor name, ok, detail in checks:\n    print(f"{'PASS' if ok else 'FAIL'} | {name} | {detail}")\n    errors += not ok\nprint(f"RESULT: {len(checks)-errors}/{len(checks)} workflow-model static checks passed")\nprint("LIMIT: XML structure only; Camunda runtime deployment and expression execution remain unverified.")\nsys.exit(1 if errors else 0)